import std.io

pub type AppError = Failed(String)

record CountIter { i: Int64, hi: Int64 }

impl Iterator<Int64> for CountIter {
    pub fn next(mut self) -> Option<Int64> {
        if self.i >= self.hi { return None }
        let v = self.i
        self.i = self.i + 1
        return Some(v)
    }
}

record Gen { hi: Int64 }

impl Iterable<Int64> for Gen {
    type Iter = CountIter
    pub fn iterator(self) -> CountIter { return CountIter { i: 0, hi: self.hi } }
}

pub fn main() effect io -> Result<(), AppError> {
    let small = Gen { hi: 5 }
    let ss = small.iterator().collect()
    for x in ss { io.println("e ${x}") }

    let g = Gen { hi: 100000 }
    let ys = g.iterator().collect()
    let n = ys.iterator().count()
    if n == 100000 { io.println("count-ok") } else { io.println("count-bad") }

    let s = ys.iterator().fold(0, |acc, x| acc + x)
    if s == 4999950000 { io.println("sum-ok") } else { io.println("sum-bad") }

    return Ok(())
}
